#include <bits/stdc++.h>
using namespace std;

int par[3001], rnk[3001];
int find(int x){return par[x]==x?x:par[x]=find(par[x]);}
bool unite(int a,int b){a=find(a);b=find(b);if(a==b)return false;if(rnk[a]<rnk[b])swap(a,b);par[b]=a;if(rnk[a]==rnk[b])rnk[a]++;return true;}

int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int N,K;
    cin>>N>>K;
    int total=N+K;
    vector<int> id(total);
    vector<long long> X(total),Y(total);
    vector<char> tp(total);
    for(int i=0;i<total;i++) cin>>id[i]>>X[i]>>Y[i]>>tp[i];

    auto cost=[&](int i,int j)->double{
        if(tp[i]=='C'&&tp[j]=='C') return 1e18;
        long long dx=X[i]-X[j], dy=Y[i]-Y[j];
        double D=(double)(dx*dx+dy*dy);
        if(tp[i]!='C'&&tp[j]!='C'&&(tp[i]=='S'||tp[j]=='S')) return 0.8*D;
        return D;
    };

    struct Edge{double w;int u,v;bool operator<(const Edge&o)const{return w<o.w;}};
    vector<Edge> edges;
    for(int i=0;i<total;i++)for(int j=i+1;j<total;j++){
        if(tp[i]=='C'&&tp[j]=='C') continue;
        edges.push_back({cost(i,j),i,j});
    }
    sort(edges.begin(),edges.end());

    for(int i=0;i<total;i++){par[i]=i;rnk[i]=0;}
    vector<pair<int,int>> tree;
    int need=N-1; // connect N non-relay nodes
    for(auto&e:edges){
        if(find(e.u)!=find(e.v)){
            unite(e.u,e.v);
            tree.push_back({e.u,e.v});
        }
    }

    // Prune leaf relays
    bool changed=true;
    while(changed){
        changed=false;
        map<int,int> deg;
        for(auto&[u,v]:tree){deg[u]++;deg[v]++;}
        set<int> rem;
        for(int i=0;i<total;i++) if(tp[i]=='C'&&deg[i]<=1){rem.insert(i);changed=true;}
        if(changed){
            vector<pair<int,int>> nt;
            for(auto&[u,v]:tree) if(!rem.count(u)&&!rem.count(v)) nt.push_back({u,v});
            tree=nt;
        }
    }

    set<int> relays;
    for(auto&[u,v]:tree){if(tp[u]=='C')relays.insert(u);if(tp[v]=='C')relays.insert(v);}

    {
        bool first=true;
        for(int c:relays){if(!first)cout<<"#";cout<<id[c];first=false;}
        cout<<"\n";
    }
    {
        bool first=true;
        for(auto&[u,v]:tree){if(!first)cout<<"#";cout<<id[u]<<"-"<<id[v];first=false;}
        cout<<"\n";
    }
}
